package database

import (
	"context"
	"database/sql"
	"errors"
	"net"
	"strings"
	"syscall"

	"github.com/gravitational/trace"
	mssql "github.com/microsoft/go-mssqldb"
	"github.com/microsoft/go-mssqldb/msdsn"
	"github.com/sirupsen/logrus"

	"github.com/gravitational/teleport/lib/defaults"
)

// SQLServerPinger implements the DatabasePinger interface for the SQL Server protocol.
type SQLServerPinger struct{}

// Ping connects to SQL Server and verifies the connection using the supplied context.
func (p *SQLServerPinger) Ping(ctx context.Context, params PingParams) error {
	if err := params.CheckAndSetDefaults(defaults.ProtocolSQLServer); err != nil {
		return trace.Wrap(err)
	}
	if params.Port < 1 || params.Port > 65535 {
		return trace.BadParameter("invalid SQL Server port %d", params.Port)
	}

	connector := mssql.NewConnectorConfig(msdsn.Config{
		Host:       params.Host,
		Port:       uint64(params.Port),
		User:       params.Username,
		Database:   params.DatabaseName,
		Encryption: msdsn.EncryptionDisabled,
		Protocols:  []string{"tcp"},
	}, nil)
	db := sql.OpenDB(connector)
	defer func() {
		if err := db.Close(); err != nil {
			logrus.WithError(err).Info("failed to close connection in SQLServerPinger.Ping")
		}
	}()

	if err := db.PingContext(ctx); err != nil {
		return trace.Wrap(err)
	}
	return nil
}

// IsConnectionRefusedError reports whether SQL Server could not be reached because the connection was refused.
func (p *SQLServerPinger) IsConnectionRefusedError(err error) bool {
	if err == nil {
		return false
	}
	if errors.Is(err, syscall.ECONNREFUSED) {
		return true
	}

	var netErr *net.OpError
	if errors.As(err, &netErr) && errors.Is(netErr.Err, syscall.ECONNREFUSED) {
		return true
	}

	errMsg := strings.ToLower(err.Error())
	return strings.Contains(errMsg, "connection refused") || strings.Contains(errMsg, "actively refused")
}

// IsInvalidDatabaseUserError reports whether SQL Server rejected the login credentials.
func (p *SQLServerPinger) IsInvalidDatabaseUserError(err error) bool {
	if err == nil {
		return false
	}
	if serverErr := sqlServerError(err); serverErr != nil && serverErr.Number == 18456 {
		return true
	}

	return strings.Contains(strings.ToLower(err.Error()), "login failed for user")
}

// IsInvalidDatabaseNameError reports whether SQL Server rejected the requested database name.
func (p *SQLServerPinger) IsInvalidDatabaseNameError(err error) bool {
	if err == nil {
		return false
	}
	if serverErr := sqlServerError(err); serverErr != nil {
		switch serverErr.Number {
		case 4060, 911:
			return true
		}
	}

	errMsg := strings.ToLower(err.Error())
	return strings.Contains(errMsg, "cannot open database") ||
		strings.Contains(errMsg, "database does not exist") ||
		strings.Contains(errMsg, "database not found")
}

func sqlServerError(err error) *mssql.Error {
	var serverErr *mssql.Error
	if errors.As(err, &serverErr) {
		return serverErr
	}
	return nil
}
